cat /home/ubuntu/.agent-ml-research-idea_gen_0509_17/projects/recovery_aware_struct_prune/registry.yaml | python3 -c "
import yaml, sys, json
data = yaml.safe_load(sys.stdin)
for eid in ['grasp_baseline_westd','eval_sft_grasp_20','eval_sft_alpha_2p0']:
    exp = data.get('experiments', {}).get(eid)
    if exp:
        print(f'{eid}: status={exp.get(\"status\")}, conclusion={exp.get(\"conclusion\",\"—\")}')
        m = exp.get('metrics',{})
        if m: print(f'  metrics: {json.dumps({k:v for k,v in m.items() if \"accuracy\" in k or k==\"n_correct\"}, default=str)}')
"

